   850      unsigned int count = thiz()->tableCount;
   851      for (unsigned int i = 0; i < count; i++)
   852      {
   853        if (st->u.header.coverage & st->u.header.CrossStream)
   854          return true;
   855        st = &StructAfter<SubTable> (*st);
   856      }
   857      return false;
   858    }
