   878    inline bool apply (AAT::hb_aat_apply_context_t *c) const
   879    {
   880      typedef typename T::SubTable SubTable;
   881
   882      bool ret = false;
   883      bool seenCrossStream = false;
   884      c->set_lookup_index (0);
   885      const SubTable *st = &thiz()->firstSubTable;
   886      unsigned int count = thiz()->tableCount;
   887      for (unsigned int i = 0; i < count; i++)
   888      {
   889        bool reverse;
   890
   891        if (!T::Types::extended && (st->u.header.coverage & st->u.header.Variation))
   892          goto skip;
   893
   894        if (HB_DIRECTION_IS_HORIZONTAL (c->buffer->props.direction) != st->u.header.is_horizontal ())
   895          goto skip;
   896
   897        reverse = bool (st->u.header.coverage & st->u.header.Backwards) !=
   898                  HB_DIRECTION_IS_BACKWARD (c->buffer->props.direction);
   899
   900        if (!c->buffer->message (c->font, "start %c%c%c%c subtable %d", HB_UNTAG (thiz()->tableTag), c->lookup_index))
   901          goto skip;
   902
   903        if (!seenCrossStream &&
   904            (st->u.header.coverage & st->u.header.CrossStream))
   905        {
   906          /* Attach all glyphs into a chain. */
   907          seenCrossStream = true;
   908          hb_glyph_position_t *pos = c->buffer->pos;
   909          unsigned int count = c->buffer->len;
   910          for (unsigned int i = 0; i < count; i++)
   911          {
   912            pos[i].attach_type() = ATTACH_TYPE_CURSIVE;
   913            pos[i].attach_chain() = HB_DIRECTION_IS_FORWARD (c->buffer->props.direction) ? -1 : +1;
   914            /* We intentionally don't set HB_BUFFER_SCRATCH_FLAG_HAS_GPOS_ATTACHMENT,
   915             * since there needs to be a non-zero attachment for post-positioning to
   916             * be needed. */
   917          }
   918        }
   919
   920        if (reverse)
   921          c->buffer->reverse ();
   922
   923        c->sanitizer.set_object (*st);
   924
   925        ret |= st->dispatch (c);
   926
   927        if (reverse)
   928          c->buffer->reverse ();
   929
   930        (void) c->buffer->message (c->font, "end %c%c%c%c subtable %d", HB_UNTAG (thiz()->tableTag), c->lookup_index);
   931
   932      skip:
   933        st = &StructAfter<SubTable> (*st);
   934        c->set_lookup_index (c->lookup_index + 1);
   935      }
   936
   937      return ret;
   938    }
   939
   940    inline bool sanitize (hb_sanitize_context_t *c) const
   941    {
   942      TRACE_SANITIZE (this);
   943      if (unlikely (!thiz()->version.sanitize (c) ||
   944                    thiz()->version < T::minVersion ||
   945                    !thiz()->tableCount.sanitize (c)))
   946        return_trace (false);
   947
   948      typedef typename T::SubTable SubTable;
   949
   950      const SubTable *st = &thiz()->firstSubTable;
   951      unsigned int count = thiz()->tableCount;
   952      for (unsigned int i = 0; i < count; i++)
   953      {
   954        if (unlikely (!st->sanitize (c)))
   955          return_trace (false);
   956        st = &StructAfter<SubTable> (*st);
   957      }
   958
   959      return_trace (true);
   960    }
